package br.com.admeclesial.application.projeto;
import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.domain.projeto.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import br.com.admeclesial.infrastructure.persistence.projeto.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class RecursoVinculadoApplicationServiceTest { @Mock RecursoVinculadoRepository repo; @Mock DestinacaoContribuicaoRepository destinos; @Mock ContribuicaoRepository contribuicoes; @Mock FonteRecursoProjetoRepository fontes; @Mock ProjetoRepository projetos; @Mock UtilizacaoRecursoRepository utilizacoes; @Mock MovimentacaoFinanceiraRepository movimentos; @Mock ContaFinanceiraRepository contas;
@Test void deveCriarRecursoAPartirDeDestinacaoEspecifica(){var d=new DestinacaoContribuicao();setId(d,2L);d.setContribuicaoId(1L);d.setTipo(TipoDestinacaoContribuicao.FINALIDADE_ESPECIFICA);d.setValor(new BigDecimal("300"));var c=new Contribuicao();setId(c,1L);c.setOrganizacaoEclesialId(10L);var du=UUID.randomUUID();when(destinos.findByUuid(du)).thenReturn(Optional.of(d));when(contribuicoes.findById(1L)).thenReturn(Optional.of(c));when(repo.findByDestinacaoContribuicaoId(2L)).thenReturn(Optional.empty());when(repo.save(any())).thenAnswer(i->i.getArgument(0));var s=new RecursoVinculadoApplicationService(repo,destinos,contribuicoes,fontes,projetos,utilizacoes,movimentos,contas);var r=s.criar(new RecursoVinculadoRequest(du,"Telhado",null));assertEquals(new BigDecimal("300"),r.getValorOriginal());assertEquals(StatusRecursoVinculado.DISPONIVEL,r.getStatus());assertEquals(10L,r.getOrganizacaoEclesialId());}
@Test void naoPermiteAlocarAcimaDoRecurso(){var p=new Projeto();setId(p,1L);p.setOrganizacaoEclesialId(10L);p.setStatus(StatusProjeto.PLANEJADO);var r=new RecursoVinculado();setId(r,2L);r.setOrganizacaoEclesialId(10L);r.setValorOriginal(new BigDecimal("100"));r.setStatus(StatusRecursoVinculado.DISPONIVEL);var pu=UUID.randomUUID();var ru=UUID.randomUUID();when(projetos.findByUuid(pu)).thenReturn(Optional.of(p));when(repo.findByUuid(ru)).thenReturn(Optional.of(r));when(fontes.sumValorAlocadoPorRecurso(2L)).thenReturn(new BigDecimal("80"));var s=new RecursoVinculadoApplicationService(repo,destinos,contribuicoes,fontes,projetos,utilizacoes,movimentos,contas);assertThrows(IllegalArgumentException.class,()->s.alocar(pu,new FonteRecursoProjetoRequest(ru,new BigDecimal("21"),null)));}
@Test void naoPermiteUtilizacaoComMovimentacaoDeEntrada(){var fonte=new FonteRecursoProjeto();setId(fonte,3L);fonte.setRecursoVinculadoId(2L);fonte.setValorAlocado(new BigDecimal("100"));var mov=new MovimentacaoFinanceira();setId(mov,4L);mov.setTipo(TipoMovimentacaoFinanceira.ENTRADA);var fu=UUID.randomUUID();var mu=UUID.randomUUID();when(fontes.findByUuid(fu)).thenReturn(Optional.of(fonte));when(movimentos.findByUuid(mu)).thenReturn(Optional.of(mov));var s=new RecursoVinculadoApplicationService(repo,destinos,contribuicoes,fontes,projetos,utilizacoes,movimentos,contas);assertThrows(IllegalArgumentException.class,()->s.utilizar(new UtilizacaoRecursoRequest(fu,mu,new BigDecimal("10"),null)));}
private static void setId(Object o,long id){try{var f=o.getClass().getDeclaredField("id");f.setAccessible(true);f.set(o,id);}catch(Exception e){throw new RuntimeException(e);}} }
